CREATE TABLE almacenes (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo VARCHAR(30) NOT NULL, nombre VARCHAR(120) NOT NULL, direccion VARCHAR(255), activo BOOLEAN NOT NULL DEFAULT TRUE,
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT uq_almacenes_codigo UNIQUE(codigo)
);
CREATE TABLE stock (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, producto_id BIGINT NOT NULL REFERENCES productos(id), almacen_id BIGINT NOT NULL REFERENCES almacenes(id), cantidad NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(cantidad >= 0), stock_reservado NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(stock_reservado >= 0),
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT uq_stock_producto_almacen UNIQUE(producto_id,almacen_id)
);
CREATE TABLE movimientos_inventario (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, producto_id BIGINT NOT NULL REFERENCES productos(id), almacen_id BIGINT NOT NULL REFERENCES almacenes(id), tipo VARCHAR(30) NOT NULL, cantidad NUMERIC(14,3) NOT NULL CHECK(cantidad > 0), costo_unitario NUMERIC(14,2), saldo_cantidad NUMERIC(14,3) NOT NULL, costo_promedio NUMERIC(14,2), referencia VARCHAR(100), motivo VARCHAR(255), fecha TIMESTAMPTZ NOT NULL DEFAULT now(),
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX idx_movimientos_producto_fecha ON movimientos_inventario(producto_id,fecha DESC);
CREATE INDEX idx_movimientos_almacen ON movimientos_inventario(almacen_id,fecha DESC);
